ALTER TABLE public.provider_network_profiles ADD COLUMN IF NOT EXISTS service_base_address text, ADD COLUMN IF NOT EXISTS service_base_lat double precision, ADD COLUMN IF NOT EXISTS service_base_lng double precision, ADD COLUMN IF NOT EXISTS service_base_verified_at timestamptz, ADD COLUMN IF NOT EXISTS approved_service_types text[] NOT NULL DEFAULT '{}', ADD COLUMN IF NOT EXISTS eligibility_expires_at timestamptz;
CREATE OR REPLACE FUNCTION public.guard_network_profile_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.workspace_id:=OLD.workspace_id; NEW.updated_at:=now(); NEW.updated_by:=auth.uid(); IF auth.uid() IS NOT NULL AND NOT public.is_master_admin(auth.uid()) THEN NEW.approved_service_types:=OLD.approved_service_types; NEW.eligibility_expires_at:=OLD.eligibility_expires_at; NEW.service_base_verified_at:=OLD.service_base_verified_at; NEW.service_base_lat:=OLD.service_base_lat; NEW.service_base_lng:=OLD.service_base_lng; IF NEW.service_base_address IS DISTINCT FROM OLD.service_base_address THEN NEW.service_base_verified_at:=NULL; NEW.service_base_lat:=NULL; NEW.service_base_lng:=NULL; END IF; END IF; RETURN NEW; END $$;
ALTER TABLE public.trips ADD COLUMN IF NOT EXISTS network_provider_workspace_id uuid REFERENCES public.workspaces(id), ADD COLUMN IF NOT EXISTS network_distribution_id uuid, ADD COLUMN IF NOT EXISTS network_status text;
ALTER TABLE public.ride_requests ADD COLUMN IF NOT EXISTS network_status text;
CREATE TABLE public.trip_distributions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), mfn_id text NOT NULL UNIQUE DEFAULT ('MFN-D-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))), request_id uuid REFERENCES public.ride_requests(id), trip_id uuid REFERENCES public.trips(id), source_workspace_id uuid REFERENCES public.workspaces(id), original_person_id uuid, original_person_mfn_id text, original_workspace_mfn_id text, acting_person_id uuid NOT NULL, acting_person_mfn_id text, represented_person_id uuid, submission_source text NOT NULL, source_mfn_id text NOT NULL, service_type text NOT NULL, pickup_area text NOT NULL, destination_area text NOT NULL, pickup_date date NOT NULL, pickup_time time NOT NULL, trip_type text NOT NULL, estimated_miles numeric, amount_cents integer NOT NULL CHECK(amount_cents>0), capability text NOT NULL, pickup_lat double precision NOT NULL, pickup_lng double precision NOT NULL, expires_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'ready', current_radius integer, selected_workspace_id uuid REFERENCES public.workspaces(id), selected_offer_id uuid, accepted_by uuid, approved_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(request_id IS NOT NULL OR trip_id IS NOT NULL));
GRANT SELECT ON public.trip_distributions TO authenticated; GRANT ALL ON public.trip_distributions TO service_role;
ALTER TABLE public.trip_distributions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.trip_distribution_waves (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), distribution_id uuid NOT NULL REFERENCES public.trip_distributions(id), radius_miles integer NOT NULL CHECK(radius_miles IN (20,50,100,200)), sent_by uuid NOT NULL, sent_at timestamptz NOT NULL DEFAULT now(), UNIQUE(distribution_id,radius_miles));
GRANT SELECT ON public.trip_distribution_waves TO authenticated; GRANT ALL ON public.trip_distribution_waves TO service_role;
ALTER TABLE public.trip_distribution_waves ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.provider_trip_offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), mfn_id text NOT NULL UNIQUE DEFAULT ('MFN-O-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))), distribution_id uuid NOT NULL REFERENCES public.trip_distributions(id), wave_id uuid NOT NULL REFERENCES public.trip_distribution_waves(id), provider_workspace_id uuid NOT NULL REFERENCES public.workspaces(id), amount_cents integer NOT NULL CHECK(amount_cents>0), expires_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'pending', decline_reason text, accepted_by uuid, approved_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(distribution_id,provider_workspace_id));
GRANT SELECT ON public.provider_trip_offers TO authenticated; GRANT ALL ON public.provider_trip_offers TO service_role;
ALTER TABLE public.provider_trip_offers ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.trip_offer_negotiations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), offer_id uuid NOT NULL REFERENCES public.provider_trip_offers(id), actor_id uuid NOT NULL, actor_mfn_id text, side text NOT NULL CHECK(side IN ('provider','source')), action text NOT NULL CHECK(action IN ('counter','revise','accept','decline')), amount_cents integer, business_note text CHECK(length(business_note)<=300), expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.trip_offer_negotiations TO authenticated; GRANT ALL ON public.trip_offer_negotiations TO service_role;
ALTER TABLE public.trip_offer_negotiations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.trip_network_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), distribution_id uuid NOT NULL REFERENCES public.trip_distributions(id), offer_id uuid REFERENCES public.provider_trip_offers(id), actor_id uuid, actor_mfn_id text, event_type text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.trip_network_events TO authenticated; GRANT ALL ON public.trip_network_events TO service_role;
ALTER TABLE public.trip_network_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.trip_network_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), automatic_expansion boolean NOT NULL DEFAULT false CHECK(automatic_expansion=false), wave_50_delay_minutes integer CHECK(wave_50_delay_minutes>0), wave_100_delay_minutes integer CHECK(wave_100_delay_minutes>0), wave_200_delay_minutes integer CHECK(wave_200_delay_minutes>0), updated_by uuid, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.trip_network_settings TO authenticated; GRANT ALL ON public.trip_network_settings TO service_role;
ALTER TABLE public.trip_network_settings ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX trip_distribution_active_request ON public.trip_distributions(request_id) WHERE status NOT IN ('closed','canceled','unavailable');
CREATE UNIQUE INDEX trip_distribution_active_trip ON public.trip_distributions(trip_id) WHERE status NOT IN ('closed','canceled','unavailable');
CREATE OR REPLACE FUNCTION public.network_workspace_access(_ws uuid,_manage boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=_ws AND m.user_id=auth.uid() AND w.status='active' AND p.status='active' AND NOT m.is_contractor AND (m.role IN ('owner','admin') OR m.can_manage_trips)) $$;
CREATE OR REPLACE FUNCTION public.network_source_access(_id uuid,_manage boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.trip_distributions d WHERE d.id=_id AND ((public.admin_can('requests',CASE WHEN _manage THEN 'manage' ELSE 'read' END) AND public.admin_can_account(d.source_workspace_id)) OR public.network_workspace_access(d.source_workspace_id,_manage) OR (d.original_person_id=auth.uid() AND d.source_workspace_id IS NULL AND EXISTS(SELECT 1 FROM public.user_profiles p WHERE p.user_id=auth.uid() AND p.status='active')))) $$;
CREATE OR REPLACE FUNCTION public.network_offer_access(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.provider_trip_offers o WHERE o.id=_id AND (public.network_workspace_access(o.provider_workspace_id,true) OR public.network_source_access(o.distribution_id,false))) $$;
REVOKE ALL ON FUNCTION public.network_workspace_access(uuid,boolean),public.network_source_access(uuid,boolean),public.network_offer_access(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.network_workspace_access(uuid,boolean),public.network_source_access(uuid,boolean),public.network_offer_access(uuid) TO authenticated,service_role;
CREATE POLICY source_distributions ON public.trip_distributions FOR SELECT TO authenticated USING(public.network_source_access(id,false));
CREATE POLICY source_waves ON public.trip_distribution_waves FOR SELECT TO authenticated USING(public.network_source_access(distribution_id,false));
CREATE POLICY addressed_offers ON public.provider_trip_offers FOR SELECT TO authenticated USING(public.network_offer_access(id));
CREATE POLICY authorized_negotiations ON public.trip_offer_negotiations FOR SELECT TO authenticated USING(public.network_offer_access(offer_id));
CREATE POLICY source_events ON public.trip_network_events FOR SELECT TO authenticated USING(public.network_source_access(distribution_id,false));
CREATE POLICY master_settings ON public.trip_network_settings FOR ALL TO authenticated USING(public.is_master_admin(auth.uid())) WITH CHECK(public.is_master_admin(auth.uid()));
CREATE POLICY selected_provider_trips ON public.trips FOR SELECT TO authenticated USING(network_provider_workspace_id IS NOT NULL AND (public.network_workspace_access(network_provider_workspace_id,true) OR EXISTS(SELECT 1 FROM public.drivers d JOIN public.workspace_members m ON m.workspace_id=d.workspace_id AND m.user_id=d.user_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE d.id=trips.driver_id AND d.user_id=auth.uid() AND d.workspace_id=trips.network_provider_workspace_id AND p.status='active')));
CREATE OR REPLACE FUNCTION public.network_audit(_distribution uuid,_offer uuid,_type text,_details jsonb DEFAULT '{}') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.trip_network_events(distribution_id,offer_id,actor_id,actor_mfn_id,event_type,details) SELECT _distribution,_offer,auth.uid(),p.mfn_id,_type,_details FROM (SELECT 1) a LEFT JOIN public.user_profiles p ON p.user_id=auth.uid(); END $$;
REVOKE ALL ON FUNCTION public.network_audit(uuid,uuid,text,jsonb) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.network_notify(_ws uuid,_type text,_offer uuid,_important boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.notifications(user_id,type,title,body,link) SELECT m.user_id,CASE WHEN _important THEN 'network_important' ELSE 'network_update' END,_type,'Controlled trip network status updated. Sign in to review.', '/portal/trips' FROM public.workspace_members m JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=_ws AND p.status='active' AND NOT m.is_contractor AND (m.role IN ('owner','admin') OR m.can_manage_trips); END $$;
REVOKE ALL ON FUNCTION public.network_notify(uuid,text,uuid,boolean) FROM PUBLIC,anon,authenticated;
COMMENT ON TABLE public.trip_distributions IS 'Source-linked controlled offers only, not a duplicate trip database. Exact passenger details remain in authorized requests/trips.';
COMMENT ON TABLE public.trip_offer_negotiations IS 'Append-only business negotiation history. No card charges, transfers or platform fee computation.';